const { v4: uuidv4 } = require('uuid');
require('dotenv').config();

const OPENAI_KEY = process.env.OPENAI_API_KEY;
let openai;
if (OPENAI_KEY) {
  openai = new OpenAI({ apiKey: OPENAI_KEY });
}

async function generateMessage(customer, event) {
  if (!OPENAI_KEY) {
    // fallback deterministic template for offline/demo mode
    return `Hi ${customer.name.split(' ')[0]}, we noticed a ${event.type.replace('_',' ')} — we'd love to help. Reply to this message or visit your account to take action.`;
  }

  // Use a simple prompt template. In a production LangChain pipeline, you'd
  // compose chains, tools, and prompt templates more fully.
  const model = process.env.MODEL_NAME || 'gpt-4o-mini';
  const prompt = `You are a polite marketing assistant. Given the customer and event, produce a short personalized outreach message (1-3 sentences) tailored to the customer's profile and preferred channel.\n\nCustomer: ${JSON.stringify(customer)}\nEvent: ${JSON.stringify(event)}\n\nMessage:`;

  const resp = await openai.chat.completions.create({
    model,
    messages: [{ role: 'system', content: 'You are a helpful assistant.' }, { role: 'user', content: prompt }],
    max_tokens: 200,
    temperature: 0.7,
  });

  const message = resp.choices?.[0]?.message?.content?.trim();
  return message || '';
}

module.exports = { generateMessage };
"}

{"path": "src/sendAgent.js", "content": "const { getDb } = require('./db');
require('dotenv').config();

const SANDBOX = (process.env.SANDBOX_SEND || 'true') === 'true';

async function sendMessage(outreach) {
  // outreach: { eventId, customerId, channel, message }
  // In sandbox mode we do not actually send. We record the attempt in outreach_logs.
  const db = await getDb();
  const logs = db.collection('outreach_logs');
  const record = {
    logId: outreach.logId,
    eventId: outreach.eventId,
    customerId: outreach.customerId,
    channel: outreach.channel,
    message: outreach.message,
    status: SANDBOX ? 'mocked' : 'sent',
    sentAt: new Date(),
  };
  await logs.insertOne(record);
  if (SANDBOX) {
    console.log('[sendAgent] sandbox send:', record);
    return { ok: true, sandbox: true };
  }
  // TODO: integrate with real provider
  console.log('[sendAgent] would send via real provider:', record);
  return { ok: true, sandbox: false };
}

module.exports = { sendMessage };
"}

{"path": "src/orchestrator.js", "content": "const { v4: uuidv4 } = require('uuid');
const { getDb } = require('./db');
const copyAgent = require('./copyAgent');
const sendAgent = require('./sendAgent');

async function processEvent(event) {
  const db = await getDb();
  const customers = db.collection('customers');
  const cust = await customers.findOne({ customerId: event.customerId });
  if (!cust) {
    console.warn('No customer found for event', event);
    return;
  }
  // call copy agent
  const message = await copyAgent.generateMessage(cust, event);
  const outreach = {
    logId: uuidv4(),
    eventId: event.eventId,
    customerId: event.customerId,
    channel: cust.preferred_channel || 'email',
    message,
  };
  const result = await sendAgent.sendMessage(outreach);
  return { outreach, result };
}

module.exports = { processEvent };
"}

