const { getDb, getClient } = require('./db');
const orchestrator = require('./orchestrator');

async function main() {
  const client = await getClient();
  const db = await getDb();
  try {
    const events = await db.collection('events').find({ type: { $in: ['cart_abandon', 'contract_renewal', 'birthday'] } }).toArray();
    console.log('Found events to process:', events.length);
    for (const ev of events) {
      console.log('Processing', ev.eventId, ev.type);
      const res = await orchestrator.processEvent(ev);
      console.log('Processed result:', res && res.outreach && res.outreach.logId);
    }
  } catch (err) {
    console.error('run_once error', err);
  } finally {
    await client.close();
  }
}

if (require.main === module) main();
"}

{"path": "src/listener.js", "content": "#!/usr/bin/env node
const { getDb, getClient } = require('./db');
const orchestrator = require('./orchestrator');

async function run() {
  const client = await getClient();
  const db = await getDb();
  const coll = db.collection('events');
  console.log('Opening change stream on events collection...');
  const changeStream = coll.watch([], { fullDocument: 'updateLookup' });
  changeStream.on('change', async (change) => {
    // We only care about insert or replace or update that yields a qualifying event
    const doc = change.fullDocument;
    if (!doc) return;
    if (['cart_abandon', 'contract_renewal', 'birthday'].includes(doc.type)) {
      console.log('Change stream observed qualifying event:', doc.eventId, doc.type);
      try {
        await orchestrator.processEvent(doc);
      } catch (err) {
        console.error('Orchestration failed', err);
      }
    }
  });

  process.on('SIGINT', async () => {
    console.log('Shutting down...');
    await changeStream.close();
    await client.close();
    process.exit(0);
  });
}

if (require.main === module) run();
module.exports = { run };
"}

{"path": "src/server.js", "content": "const express = require('express');
const { getDb } = require('./db');
const app = express();
require('dotenv').config();
const PORT = process.env.PORT || 3000;

app.get('/logs', async (req, res) => {
  const db = await getDb();
  const logs = await db.collection('outreach_logs').find().sort({ sentAt: -1 }).limit(50).toArray();
  res.json({ count: logs.length, logs });
});

if (require.main === module) {
  app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
}

module.exports = app;
"}

{"path": "src/test_runner.js", "content": "// Simple smoke tests that try to run seed and run-once in offline-safe ways.
const { execSync } = require('child_process');

function run(cmd) {
  console.log('> ' + cmd);
  try {
    const out = execSync(cmd, { stdio: 'inherit' });
    return true;
  } catch (err) {
    console.error('Cmd failed', cmd, err && err.message);
    return false;
  }
}

// Run seed
if (!run('node src/seed.js')) process.exit(1);

// Run run-once
if (!run('node src/run_once.js')) process.exit(1);

console.log('Smoke run completed.');
"}

